"""Walking task driven by a CPG controller."""
# ruff: noqa: F821

import numpy as np
from dm_control import mjcf
from dm_control.utils import rewards

from .base import Walking
from .constants import _TERMINAL_ANGVEL, _TERMINAL_LINVEL
from .cpg import FlyBodyCPGController


class WalkCPG(Walking):
    """Class for open-loop CPG walking control."""

    def __init__(
        self,
        cpg_controller: FlyBodyCPGController,
        claw_friction: float | None = 1.0,
        position_gain_scale: float = 1.0,
        **kwargs,
    ):
        """Walking task where leg joints are generated by a CPG controller.

        Args:
            cpg_controller: Configured 48-DOF CPG returning leg position
                targets in the environment leg order.
            claw_friction: Friction of claw.
            position_gain_scale: Multiplier for FlyBody's leg position-servo
                gain and matching affine position bias, without changing the
                source angles or model units.
            **kwargs: Arguments passed to the superclass constructor.
        """
        super().__init__(add_ghost=False, **kwargs)

        if position_gain_scale <= 0:
            raise ValueError("position_gain_scale must be positive")
        self._position_gain_scale = float(position_gain_scale)
        if self._position_gain_scale != 1.0 and not kwargs.get("force_actuators", False):
            self._scale_leg_position_gains(self._position_gain_scale)

        self._cpg_controller = cpg_controller
        joint_names = getattr(self._cpg_controller, "flybody_joint_names", None)
        self._cpg_joints = (
            [self._walker.mjcf_model.find("joint", name) for name in joint_names]
            if joint_names is not None else None
        )
        # Kept for diagnostics/examples: ``before_step`` is the single place
        # where a generated CPG target is actually applied.  Exposing a copy
        # lets a renderer inspect the exact target without advancing the CPG
        # a second time (which would otherwise double its apparent frequency).
        self._last_cpg_action = None

        self._legs_action_indices = np.asarray(
            self._walker._action_indices["legs"], dtype=int
        )
        if self._legs_action_indices.size != len(self._cpg_controller.all_leg_dofs):
            raise ValueError(
                "Leg action dimension mismatch between walker action space and CPG output."
            )

        self._speed = 1.0
        self._turn = 0.0

        # Validate the 48-DOF FlyBody action contract at construction time.
        if len(self._cpg_controller.all_leg_dofs) != self._legs_action_indices.size:
            raise ValueError(
                "CPG controller must emit one action for every FlyBody leg actuator "
                f"({self._legs_action_indices.size}); got "
                f"{len(self._cpg_controller.all_leg_dofs)}."
            )

        # Maybe change default claw friction.
        if claw_friction is not None:
            self._walker.mjcf_model.find(
                "default", "adhesion-collision"
            ).geom.friction = (claw_friction,)

    def _scale_leg_position_gains(self, scale: float) -> None:
        """Scale inherited general-actuator position gains before compilation.

        FlyBody expresses its position servos as ``general`` actuators with
        ``gainprm=k`` and ``biasprm=(0, -k)``.  Scaling only ``gainprm`` would
        introduce a non-zero equilibrium force, so the matching position bias
        is scaled as well.
        """
        for actuator in self._walker.mjcf_model.find_all("actuator"):
            if actuator.tag != "general" or actuator.name is None:
                continue
            if not any(token in actuator.name for token in ("T1_", "T2_", "T3_")):
                continue
            # Resolve the inherited class values without mutating shared
            # defaults (which could also affect unrelated actuators).
            cls = actuator.dclass
            gain = bias = None
            while cls is not None:
                if gain is None and cls.general.gainprm is not None:
                    gain = np.asarray(cls.general.gainprm, dtype=float)
                if bias is None and cls.general.biasprm is not None:
                    bias = np.asarray(cls.general.biasprm, dtype=float)
                if gain is not None and bias is not None:
                    break
                cls = cls.parent
            if gain is not None:
                actuator.gainprm = tuple((gain * scale).tolist())
            if bias is not None:
                actuator.biasprm = tuple((bias * scale).tolist())

    def initialize_episode(self, physics: "mjcf.Physics", random_state: np.random.RandomState):
        """Set initial pose and reset CPG state at episode start."""
        super().initialize_episode(physics, random_state)

        reset_controller = getattr(self._cpg_controller, "reset", None)
        if reset_controller is not None:
            reset_controller()

        # Start from the center of the recorded FlyBody gait cycle so the
        # first position target does not pull the legs away from XML qpos=0.
        if self._cpg_joints is not None:
            physics.bind(self._cpg_joints).qpos = self._cpg_controller.neutral_pose.reshape(-1)
            physics.bind(self._cpg_joints).qvel = np.zeros(len(self._cpg_joints))

        # Keep wings in retracted pose in walking setup.
        physics.bind(self._wing_joints).qpos = self._wing_springrefs

    def before_step(self, physics: "mjcf.Physics", action, random_state: np.random.RandomState):
        """Ignore incoming leg actions and drive legs with CPG output."""
        generated = self._cpg_controller.step()
        if isinstance(generated, dict):
            base_action = np.asarray(generated["joints"], dtype=np.float32)
        else:
            base_action = np.asarray(generated, dtype=np.float32)
        self._last_cpg_action = base_action.copy()

        cpg_action = np.asarray(action).copy()
        cpg_action[self._legs_action_indices] = base_action

        adhesion = getattr(self._cpg_controller, "adhesion", None)
        adhesion_indices = np.asarray(self._walker._action_indices["adhesion"], dtype=int)
        if adhesion is not None and adhesion_indices.size == len(adhesion):
            cpg_action[adhesion_indices] = np.asarray(adhesion, dtype=np.float32)

        # Protect from rare NaN actions.
        cpg_action[np.isnan(cpg_action)] = 0.0

        super().before_step(physics, cpg_action, random_state)

    def set_command(self, speed: float = 1.0, turn: float = 0.0) -> None:
        """Set CPG locomotion command (positive turn is to the right).

        Speed changes the template phase rate and step magnitude; turn scales
        left and right leg excursions around their recorded neutral poses.
        A zero turn command includes the controller's calibrated straight trim.
        """
        self._speed = float(np.clip(speed, -1.0, 1.0))
        self._turn = float(np.clip(turn, -1.0, 1.0))
        setter = getattr(self._cpg_controller, "set_command", None)
        if setter is None:
            raise TypeError("CPG controller must implement set_command(speed, turn)")
        setter(speed=self._speed, turn=self._turn)

    @property
    def last_cpg_action(self):
        """Most recently applied 48-D semantic FlyBody CPG target."""
        if self._last_cpg_action is None:
            return None
        return self._last_cpg_action.copy()

    def get_reward_factors(self, physics):
        """Returns factorized reward terms."""
        # Reward for wing retraction.
        qpos_diff = physics.bind(self._wing_joints).qpos - self._wing_springrefs
        retract_wings = rewards.tolerance(
            qpos_diff,
            bounds=(0, 0),
            sigmoid="linear",
            margin=3.0,
            value_at_margin=0.0,
        )

        return np.hstack((np.array([1.0]), retract_wings))

    def check_termination(self, physics: "mjcf.Physics") -> bool:
        """Check various termination conditions."""
        linvel = np.linalg.norm(self._walker.observables.velocimeter(physics))
        angvel = np.linalg.norm(self._walker.observables.gyro(physics))

        return (
            linvel > _TERMINAL_LINVEL
            or angvel > _TERMINAL_ANGVEL
            or super().check_termination(physics)
        )

